<?php
/** Isolated SQLite regression tests for network maintenance and quota visibility. */
require __DIR__.'/network-preflight.test.php';
use App\Models\{ServerTunnel,TunnelOperation};
use App\Services\{NetworkTunnelRemote,BackpackRemote};
use Illuminate\Http\Request;
$checks=0;
$assert=function($yes,$message)use(&$checks){if(!$yes)throw new RuntimeException($message);$checks++;};
$execute=function($op,$remote)use($network,$manager){for($i=0;$i<40;$i++){(new App\Jobs\RunNetworkTunnelOperation($op->id))->handle($remote,$network,$manager);$op->refresh();if(!in_array($op->status,['queued','running']))return $op;}throw new RuntimeException('maintenance job did not terminate');};
$queue=function($t,$data)use($controller,$manager){$answer=$controller->action(Request::create('/','POST',$data),$t->fresh(),$manager);return TunnelOperation::findOrFail($answer->getData()->data->id);};
$reject=function($data,$label)use($queue,$t,$assert){try{$queue($t,$data);$assert(false,$label);}catch(Illuminate\Validation\ValidationException|Symfony\Component\HttpKernel\Exception\HttpException $e){$assert(true,$label);}};
$reject(['action'=>'optimize','sides'=>['iran']],'global host optimization requires explicit acceptance');
$reject(['action'=>'engine-update'],'update requires explicit acceptance');
$reject(['action'=>'optimize','confirm'=>true,'sides'=>['other']],'unknown host side rejected');
$reject(['action'=>'optimize','confirm'=>true,'sides'=>[]],'empty host selection rejected');
$reject(['action'=>'reset-quota','confirm'=>true],'GOST cannot reset GRE quota');
$calls=[];$failure=null;
$remote=Mockery::mock(NetworkTunnelRemote::class);
$currentVersions=false;
$remote->shouldReceive('maintenanceStatus')->andReturnUsing(function()use(&$currentVersions){return ['up_to_date'=>$currentVersions,'version'=>'3.0.0','target_version'=>'3.0.0','checked_at'=>time()];});
$remote->shouldReceive('ensure')->andReturnUsing(function($server,$engine,$version)use(&$calls){$calls[]=['ensure',$server->id,$engine,$version];});
$remote->shouldReceive('call')->andReturnUsing(function($server,$request)use(&$calls,&$failure){$calls[]=[$request['action'],$server->id];if($failure===[$request['action'],$server->id])throw new RuntimeException('simulated maintenance failure');return $request['action']==='prepare'?['checks'=>[['name'=>'ready','ok'=>true]]]:['active'=>true,'connected'=>true,'checked_at'=>time(),'quota_exhausted'=>false];});
$optimizer=Mockery::mock(BackpackRemote::class);$optCalls=[];$optFail=null;
$optimizer->shouldReceive('maintenance')->andReturnUsing(function($server,$action,$ports)use(&$optCalls,&$optFail){$optCalls[]=[$server->id,$action,$ports];return ['status'=>['optimized'=>$server->id!==$optFail],'logs'=>['host-specific optimize report']];});
$app->instance(BackpackRemote::class,$optimizer);
$before=$t->fresh()->settings;
$op=$queue($t,['action'=>'optimize','confirm'=>true,'sides'=>['iran']]);
$assert(Illuminate\Support\Facades\DB::table('speedbox_tunnel_leases')->count()===2,'optimization locks both shared hosts');
$op=$execute($op,$remote);
$assert($op->status==='succeeded'&&count($optCalls)===1&&$optCalls[0][0]===$t->iran_server_id,'only selected host is optimized');
$assert($op->result['hosts']['foreign']['skipped']===true,'unselected host explicitly skipped');
$assert($calls===[],'optimization does not install a tunnel engine or rewrite a tunnel');
$assert($t->fresh()->settings===$before,'optimization preserves GOST tunnel settings');
$assert(Illuminate\Support\Facades\DB::table('speedbox_tunnel_leases')->count()===0,'optimization releases leases');
$optFail=$t->iran_server_id;$optCalls=[];
$op=$execute($queue($t,['action'=>'optimize','confirm'=>true,'sides'=>['iran','foreign']]),$remote);
$assert($op->status==='failed'&&count($optCalls)===2,'partial host optimization failure is not reported as success');
$assert(isset($op->result['hosts']['foreign']['logs'])&&isset($op->result['hosts']['iran']['logs']),'partial failure retains both host reports');
$assert(str_contains($op->message,'بخشی'),'partial optimization does not claim a global rollback');
$optFail=null;$calls=[];
$op=$execute($queue($t,['action'=>'engine-update','confirm'=>true]),$remote);
$assert($op->status==='succeeded','pinned GOST package refresh completes');
$assert(count(array_filter($calls,fn($c)=>$c[0]==='ensure'))===2,'update verifies shipped package on both hosts');
$assert(count(array_filter($calls,fn($c)=>$c[0]==='reapply'))===2,'update reapplies selected tunnel only');
$assert($t->fresh()->settings===$before,'update preserves version, ports and enabled state');
$calls=[];$currentVersions=false;$failure=['reapply',$t->iran_server_id];
$op=$execute($queue($t,['action'=>'engine-update','confirm'=>true]),$remote);
$assert($op->status==='failed'&&count(array_filter($calls,fn($c)=>$c[0]==='rollback'))===2,'update failure rolls back both prepared hosts');
$assert($t->fresh()->settings===$before,'failed update preserves original tunnel settings');
$failure=null;
$calls=[];$currentVersions=true;
$op=$execute($queue($t,['action'=>'engine-update','confirm'=>true]),$remote);
$assert($op->status==='succeeded'&&$calls===[],'up-to-date engines never reinstall or reapply');
$assert(str_contains($op->message,'به‌روز'),'no-op update explains current status');
$optCalls=[];$calls=[];
$op=$execute($queue($t,['action'=>'maintenance-status']),$remote);
$assert($op->status==='succeeded'&&count($optCalls)===2&&$calls===[],'maintenance inspection never mutates tunnel engines');
$assert(isset($op->result['hosts'][$t->iran_server_id]['status']['up_to_date']),'engine status is indexed by host for shared maintenance UI');
$currentVersions=false;
$settings=[...$before,'engine'=>'gre','transport'=>'gre','enabled'=>true,'quota_gb'=>1,'quota_mode'=>'warn'];
$gre=ServerTunnel::create(['name'=>'GRE quota test','engine'=>'gre','kind'=>'direct','transport'=>'gre','orientation'=>'normal','iran_server_id'=>$t->iran_server_id,'foreign_server_id'=>$t->foreign_server_id,'subnet'=>9550,'remote_name'=>'sb-'.str_repeat('9',32),'secret'=>str_repeat('s',64),'settings'=>$settings,'status'=>'connected']);
$snapshots=['iran'=>['active'=>true,'connected'=>true,'quota_exhausted'=>true],'foreign'=>['active'=>true,'connected'=>true]];
$network->saveSnapshot($gre,$snapshots);
$assert($gre->fresh()->status==='degraded'&&str_contains($gre->fresh()->message,'سقف مصرف'),'quota warning is visible in card state and message');
$assert($gre->fresh()->settings['enabled']===true,'warn mode does not disable the tunnel');
$gre->update(['settings'=>[...$settings,'quota_mode'=>'enforce']]);$snapshots['iran']['active']=false;
$network->saveSnapshot($gre,$snapshots);$assert($gre->fresh()->status==='offline'&&str_contains($gre->fresh()->message,'توقف'),'enforced quota has clear stop explanation');
$gre->update(['settings'=>$settings]);$calls=[];
$op=$execute($queue($gre,['action'=>'reset-quota','confirm'=>true]),$remote);
$assert($op->status==='succeeded'&&$gre->fresh()->status==='connected','quota reset refreshes visible card state');
$assert(count(array_filter($calls,fn($c)=>$c[0]==='reset-quota'))===2&&count(array_filter($calls,fn($c)=>$c[0]==='status'))===2,'reset reads fresh snapshots on both hosts');
$assert(empty($gre->fresh()->remote_status['iran']['quota_exhausted']),'stale quota warning disappears after reset');
Mockery::close();echo "PASS: $checks network maintenance and quota assertions\n";
